[
  {
    "description": "After an upstream timeout on a refund request to the Legacy Payment API (which has no idempotency guarantees and always duplicates side effects on retry), the payment worker retries the refund without providing an idempotency key, causing a duplicate refund to be processed.",
    "rationale": "The system description explicitly states a retry after timeout occurs. The Legacy Payment API contract guarantees 'Duplicate request → duplicate side effect (always)' and 'No idempotency guarantees'. The 'missing_idempotency_key' intervention directly tests whether the worker's retry logic omits an idempotency key, which would trigger the API's duplicate side effect behavior. This distinguishes the hypothesis from scenarios where a key is present but ignored, or where the timeout occurs after commit (which would not be a retry-caused duplicate).",
    "expectedInvariant": "r04-network-idempotency",
    "interventions": [
      "timeout",
      "missing_idempotency_key"
    ],
    "confidence": 0.9
  }
]

