  {
    "description": "When a worker crashes after the Legacy Payment API commits a refund but before the worker checkpoints completion, the recovered worker replays the refund and the API charges twice because it has no idempotency guarantees and the worker lacks an idempotency key.",
    "rationale": "The prior experiment showed duplicates from timeout+missing idempotency key. This test isolates whether a crash/restart cycle (kill_worker) with a delayed response (delay_response) also produces duplicates via replay, distinguishing restart-driven replay from pure retry-driven duplication.",
    "expectedInvariant": "r04-network-idempotency",
    "interventions": [
      "delay_response",
      "kill_worker",
      "missing_idempotency_key"
    ],
    "confidence": 0.85
  }
]

